{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Test equal weighting of nonempty sequences across all four datasets by averaging the existing pointwise logistic loss within each sequence before averaging sequences. This may better match user-averaged evaluation. Only loss reduction changes; model and predictor remain compatible.",
      "edits": [
        {
          "find": "    loss = nn.functional.softplus(-pos_scores) + nn.functional.softplus(neg_scores)\n    return (loss * mask).sum() / mask.sum().clamp(min=1.0)",
          "replace": "    loss = nn.functional.softplus(-pos_scores) + nn.functional.softplus(neg_scores)\n    valid_counts = mask.sum(dim=1)\n    sequence_loss = (loss * mask).sum(dim=1) / valid_counts.clamp(min=1.0)\n    nonempty = (valid_counts > 0).to(dtype=loss.dtype)\n    return (sequence_loss * nonempty).sum() / nonempty.sum().clamp(min=1.0)"
        }
      ]
    }
  ],
  "change_summary": "Apply equal-sequence weighting to the existing logistic objective for all four category models, preserving sampling, architecture, inference and training settings."
}
